import {supplementCheckReady,supplementCheckPanel} from './supplement-check-panel.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function assessWritingDelivery({kind,text='',snapshot={},quality,qualityCurrent=true,requireSupplementCheck=false}={}){
 const issues=[],seen=new Set(),add=(code,message,material=false)=>{if(!seen.has(code+message)){seen.add(code+message);issues.push({code,message,material});}};
 if(!text.trim())add('empty','尚无正文，请先生成；缺少资料时可在下方补充。',true);
 const markers=[...text.matchAll(/(?:【[^】\n]{0,100}(?:待补充|待核对|待填写|待提供)[^】\n]*】|\[(?:待补充|待核对|待填写|待提供)[^\]\n]*\]|\{\{[^}\n]+\}\}|\bTODO\b|\bTBD\b)/gi)];
 for(const row of markers.slice(0,30))add('materials','请补充：'+row[0].replace(/^[【\[]|[】\]]$/g,'').replace(/^待(?:补充|核对|填写|提供)[：:]?\s*/,'').slice(0,200),true);
 const known=new Set([...(snapshot.materials||[]),...(snapshot.references||[])].map(row=>row.id));
 if([...text.matchAll(/\[source:([^\]]+)\]/g)].some(match=>!known.has(match[1])))add('references','存在无法对应的引用来源，请补充原文与真实题录，由系统重新整理引用。',true);
 if(kind==='summary'&&text.trim()&&!(snapshot.references||[]).some(row=>row.text?.trim())&&!(snapshot.materials||[]).some(row=>row.text?.trim()))add('references','文献综述需要可引用的摘要或正文，请补充实际文献内容。',true);
 if(qualityCurrent){for(const row of [...(quality?.consistency?.findings||[]),...(quality?.reviews||[]).flatMap(review=>review.findings||[])])if(row.category!=='language_expression'&&typeof row.quote==='string'&&row.quote.trim()&&text.includes(row.quote)){const material=['unresolved_placeholder','source_support','unknown_citation'].includes(row.category);add(row.category||'review',(material?'请补充与此处有关的真实资料：':'系统将整理此处的表达与衔接：')+row.quote.slice(0,160),material);}}
 if(requireSupplementCheck&&!supplementCheckReady(quality,{current:qualityCurrent}))add('supplement_check','补充内容尚未通过本次完整检查，请保存材料并自动完善后复查。',true);
 return {ready:!issues.length,issues:issues.slice(0,40),hasText:!!text.trim(),supplementCheck:quality?.supplementCheck,stale:!qualityCurrent};
}
export function writingDeliveryMarkup({assessment,open=false,supplement='',reference={},canComplete=false,failedMessage='',kind}={}){
 const inputs=[['title','文献题名'],['authors','作者'],['year','年份'],['doi','DOI（可选）']];
 return `<section class="wf-delivery" data-wf-delivery><header><div><span class="wf-kicker">DOCUMENT DELIVERY</span><h3>检查内容，完成交付</h3></div><span class="wf-delivery-state">${assessment.ready?'本次内容检查未发现缺项':'有待补充内容'}</span></header><div data-wf-supplement-report>${kind==='idea'?'<p class="wf-muted">核对选题范围、研究问题与拟采用方法；未开展的研究按计划表述。</p>':supplementCheckPanel(assessment.supplementCheck,{stale:assessment.stale})}</div><p class="wf-muted">${kind==='idea'?'补充选题条件与具体要求，由 AI 更新研究思路。':'缺少资料时在这里补充，系统负责完善正文、整理引用并重新检查。'}保存资料不扣写作积分，AI 完善按可用套餐次数或积分处理。</p><details class="wf-drawer" data-wf-completion data-optional-fields open><summary>补充材料，自动完善当前版本</summary>${failedMessage?`<p class="wf-notice">${esc(failedMessage)}</p>`:''}${assessment.issues.length?`<ul class="wf-delivery-issues" tabindex="0" aria-label="本次内容检查缺项">${assessment.issues.map(row=>`<li>${esc(row.message)}</li>`).join('')}</ul>`:'<p class="wf-muted">可以补充新的研究资料或更具体的要求，系统据此完善当前版本。</p>'}<label class="wf-field"><span>${kind==='idea'?'选题范围、研究问题与资源条件':'研究资料、真实记录与补充要求'}</span><textarea data-wf-supplement rows="5" maxlength="10000" placeholder="提供真实过程、数据、案例或需要补充的信息，无需自己改写文档段落。">${esc(supplement)}</textarea></label><div class="wf-actions"><button type="button" class="btn secondary" data-wf-upload="completion">上传补充材料</button><button type="button" class="btn secondary" data-wf-stored="completion">从文件管理选择</button></div><details class="wf-drawer" data-optional-fields open><summary>补充参考文献与可引用正文</summary><div class="wf-field-grid">${inputs.map(([key,label])=>`<label class="wf-field"><span>${label}</span><input data-wf-supp-reference="${key}" maxlength="${key==='year'?4:500}" value="${esc(reference[key]||'')}"></label>`).join('')}</div><label class="wf-field"><span>已核对的摘要或正文</span><textarea data-wf-supp-reference="text" rows="5" maxlength="30000">${esc(reference.text||'')}</textarea></label><button type="button" class="btn secondary" data-wf-add-supp-reference>加入文献依据</button></details><div class="wf-actions"><button type="button" class="btn primary" data-wf-complete ${canComplete?'':'disabled'}>${kind==='idea'?'补充信息并更新研究思路':'保存材料并自动完善'}</button></div>${canComplete?'':'<p class="wf-muted">填写或生成正文后，即可按原稿自动完善；已有手写内容会保留。</p>'}</details><p class="wf-muted" data-wf-delivery-status role="status"></p></section>`;
}
